window.kbPageData["views/entry/k-b4e8197069be3999"] = {"key":"entry/k-b4e8197069be3999","state":{"route":"entry/k-b4e8197069be3999"},"node":{"id":"k-b4e8197069be3999","mode":"k","title":"插板法","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["相同物品分给不同对象且各至少一个时的隔板计数公式"],"qs":["国考 2023 行政执法 行测#66"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"把 n 个相同物品分给 k 个不同对象，每个对象至少分得 1 个。若 n≥k，分配方案数等于从 n−1 个相邻间隙中选出 k−1 个放置隔板的组合数。","review":{"definition":"把 n 个相同物品分给 k 个不同对象，每个对象至少分得 1 个。若 n≥k，分配方案数等于从 n−1 个相邻间隙中选出 k−1 个放置隔板的组合数。","explanation":"先给分配对象排定顺序，隔板分出的各段依次对应各对象。隔板插在不同的内部间隙里，每段至少有一个物品，每种分配方案也唯一确定一组隔板位置。第66题把10个名额分给4个分公司，从9个间隙选3个，得到84种等可能方案。三个分公司的名额相同，数量只能是1、2或3，第四个分公司相应得到7、4或1个名额。每种数量组合都有4种选择第四个分公司的方式，因此所求概率为12/84＝1/7，对应D项。","references":[],"evidence":"每个分公司至少分配1个名额，可使用插板法解","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 行政执法 行测#66":{"paper":"国考 2023 行政执法 行测","n":66,"mod":"数量关系","src":["857378cf496f27296500.pdf",11],"asrc":["d23139fe5a0fb3115135.pdf",20],"card":"e8e48bcdd1bf70b5935a4dfb","links":[{"id":"k-b4e8197069be3999","role":"解题依据","why":"将相同名额排成一列，从相邻名额间选取三个间隙设隔板，可计得全部分配方案。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-b4e8197069be3999":[["国考 2023 行政执法 行测#66"]]}};
